export const skillBody = "---\nname: paseo-project-check\ndescription: 检查当前项目的运行入口和冒烟验证步骤。用于用户要求接手本地项目、确认如何启动或验证安装时。\n---\n\n1. 从当前工作区根目录读取项目说明和运行清单，例如 README、package.json 或项目自己的启动文档。\n2. 总结必要的运行环境、项目声明的启动命令、服务地址和一个最小验证步骤。将已检查的事实和待验证事项分别说明。\n3. 如果当前会话有 `paseo_local_demo` MCP，请调用 `local_extension_status` 并报告返回版本。以实际工具结果判断示例是否可用。\n4. 用户只要求查看时，保持检查为只读。用户已经要求运行时，使用项目明确提供的启动入口和最小验证流程。\n";
export const mcpSource = "const readline = require(\"node:readline\");\n\nconst tool = {\n  name: \"local_extension_status\",\n  description: \"Report the version of the offline Paseo sample extension.\",\n  inputSchema: { type: \"object\", properties: {}, additionalProperties: false },\n};\n\nfunction write(id, response) {\n  process.stdout.write(JSON.stringify({ jsonrpc: \"2.0\", id, ...response }) + \"\\n\");\n}\n\nreadline.createInterface({ input: process.stdin, crlfDelay: Infinity }).on(\"line\", (line) => {\n  let request;\n  try {\n    request = JSON.parse(line);\n  } catch {\n    return;\n  }\n  if (!request || request.id === undefined) return;\n  const { id, method, params } = request;\n  switch (method) {\n    case \"initialize\":\n      return write(id, {\n        result: {\n          protocolVersion: [\"2024-11-05\", \"2025-03-26\", \"2025-06-18\", \"2025-11-25\"].includes(\n            params?.protocolVersion,\n          )\n            ? params.protocolVersion\n            : \"2025-03-26\",\n          capabilities: { tools: {} },\n          serverInfo: { name: \"paseo-local-demo\", version: \"1.0.0\" },\n        },\n      });\n    case \"ping\":\n      return write(id, { result: {} });\n    case \"tools/list\":\n      return write(id, { result: { tools: [tool] } });\n    case \"tools/call\":\n      if (params?.name === tool.name) {\n        return write(id, {\n          result: {\n            content: [{ type: \"text\", text: \"Paseo Local Extensions 1.0.0 · offline MCP ready\" }],\n          },\n        });\n      }\n      return write(id, { error: { code: -32602, message: \"Unknown tool\" } });\n    default:\n      return write(id, { error: { code: -32601, message: \"Method not found\" } });\n  }\n});\n";
